import * as React from "react"

function ProductsShowItems({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="products-show-items"
      className={className}
      {...props}
    >
      <div className="flex flex-col items-center space-y-4">
              <div className="w-full max-w-3xl">
                  <img id="main-image" src="https://raw.githubusercontent.com/prebuiltui/prebuiltui/main/assets/gallery/slide1.png" className="w-full rounded-lg" alt="Main Image" />
              </div>

              <div className="grid grid-cols-4 max-w-3xl gap-4" id="thumbnail-container">

                  <img src="https://raw.githubusercontent.com/prebuiltui/prebuiltui/main/assets/gallery/slide1.png" className="thumb rounded-lg md24 h-14 object-cover cursor-pointer hover80" alt="Thumb 1" 
                   />

                  <img src="https://raw.githubusercontent.com/prebuiltui/prebuiltui/main/assets/gallery/slide2.png" className="thumb rounded-lg md24 h-14 object-cover cursor-pointer hover80" alt="Thumb 2"
                   />

                  <img src="https://raw.githubusercontent.com/prebuiltui/prebuiltui/main/assets/gallery/slide3.png" className="thumb rounded-lg md24 h-14 object-cover cursor-pointer hover80" alt="Thumb 3"
                   />

                  <img src="https://raw.githubusercontent.com/prebuiltui/prebuiltui/main/assets/gallery/slide4.png" className="thumb rounded-lg md24 h-14 object-cover cursor-pointer hover80" alt="Thumb 4"
                   />

              </div>
          </div>
    </div>
  )
}

export { ProductsShowItems }
